import{_ as i,y as s,a as g,o as l,a2 as a,D as n,g as t,I as r}from"./chunks/framework.DCcmcJcL.js";const I=JSON.parse('{"title":"Generate Product Images","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/generate-images.md","filePath":"generative-ai/generate-images.md","lastUpdated":1789441803000}'),d={name:"generative-ai/generate-images.md"};function h(p,e,u,m,c,f){const o=s("ImagePopup");return l(),g("div",null,[e[3]||(e[3]=a('<h1 id="generate-product-images" tabindex="-1">Generate Product Images <a class="header-anchor" href="#generate-product-images" aria-label="Permalink to &quot;Generate Product Images&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Admin panel</span></div><p>Magic AI creates images from a written description, right in the admin&#39;s image uploader. You choose how many images to create, their shape and their quality. Then you pick the ones you like and add them to the product like any uploaded photo. Nothing is added until you click <strong>Apply</strong>, and nothing is kept until you save the product.</p><h2 id="where-the-magic-ai-tile-appears" tabindex="-1">Where the Magic AI tile appears <a class="header-anchor" href="#where-the-magic-ai-tile-appears" aria-label="Permalink to &quot;Where the Magic AI tile appears&quot;">​</a></h2><p>The <strong>Magic AI</strong> tile, labelled <strong>Generate Image</strong>, sits beside <strong>Add Image</strong> in the admin&#39;s image uploaders:</p><ul><li><strong>Catalog &gt;&gt; Products</strong>: the <strong>Images</strong> section of a product, which is where you&#39;ll use it most.</li><li><strong>Other image fields that use the same uploader</strong>, such as a category&#39;s logo and banner under <strong>Catalog &gt;&gt; Categories</strong>, and a channel&#39;s images under <strong>Settings &gt;&gt; Channels</strong>.</li></ul><p>The tile appears only when Magic AI and image generation are both switched on. In an uploader that takes a single image, it&#39;s shown only while the field is empty.</p>',7)),n(o,{src:"/images/generative-ai/generate-images-button.png",alt:"The Images section of a product with the Magic AI Generate Image tile beside Add Image"}),e[4]||(e[4]=t("h2",{id:"generate-images",tabindex:"-1"},[r("Generate images "),t("a",{class:"header-anchor",href:"#generate-images","aria-label":'Permalink to "Generate images"'},"​")],-1)),t("ol",null,[e[1]||(e[1]=a("<li><p>Open the product under <strong>Catalog &gt;&gt; Products</strong>.</p></li><li><p>In the <strong>Images</strong> section, click <strong>Magic AI</strong>. The <strong>AI Image Generation</strong> dialog opens.</p></li><li><p>In <strong>Prompt</strong>, describe the image. For example: &quot;A blue cotton zipper hoodie on a plain light grey background, soft studio lighting, front view&quot;.</p></li><li><p>Enter the <strong>Number of Images</strong>, from 1 to 10.</p></li><li><p>Choose the <strong>Size</strong>: <strong>Square (1:1)</strong>, <strong>Portrait (2:3)</strong> or <strong>Landscape (3:2)</strong>.</p></li><li><p>Choose the <strong>Quality</strong>: <strong>High</strong>, <strong>Medium</strong> or <strong>Low</strong>.</p></li><li><p>Choose the <strong>Model</strong>, for example <strong>OpenAI: GPT Image 1.5</strong>. The list holds the image models of the providers allowed for image generation.</p></li>",7)),t("li",null,[e[0]||(e[0]=t("p",null,[r("Click "),t("strong",null,"Generate"),r(". The button reads "),t("strong",null,"Generating..."),r(" while the images are created.")],-1)),n(o,{src:"/images/generative-ai/image-generate.png",alt:"The AI Image Generation dialog with Prompt, Number of Images, Size, Quality and Model filled in"})]),e[2]||(e[2]=a("<li><p>Click each image you want to keep. A selected image gets a blue border.</p></li><li><p>If none of them are right, click <strong>Regenerate</strong> to create a new set with the same settings.</p></li><li><p>Click <strong>Apply</strong>. The selected images are added after the product&#39;s existing images.</p></li><li><p>Click <strong>Save Product</strong>.</p></li>",4))]),e[5]||(e[5]=a('<p>To change the prompt instead of regenerating, click the arrow at the top of the dialog.</p><h2 id="after-you-apply" tabindex="-1">After you apply <a class="header-anchor" href="#after-you-apply" aria-label="Permalink to &quot;After you apply&quot;">​</a></h2><ul><li><strong>The new images work like uploaded ones.</strong> Drag them into a different order, or remove the ones you don&#39;t need.</li><li><strong>They&#39;re kept only when you save.</strong> If you leave the product without saving, the generated images are discarded.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Refine the prompt with one image at medium quality first</strong>, then generate the final set. Higher quality and more images take longer and cost more at the provider.</li><li><strong>Describe the background, angle and lighting</strong>, as well as the product itself.</li><li><strong>Make sure images show the product you really sell.</strong> Use generated images for backgrounds and lifestyle scenes, and check every detail before shoppers see it.</li></ul><h2 id="what-you-control" tabindex="-1">What you control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What you control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong></td><td>Switches every Magic AI feature on or off</td></tr><tr><td><strong>Enabled</strong> in the <strong>Image Generation</strong> section of <strong>Configure &gt;&gt; Magic AI &gt;&gt; Admin Features</strong></td><td>Shows the <strong>Magic AI</strong> tile in the image uploaders</td></tr><tr><td><strong>Providers</strong> in the <strong>Image Generation</strong> section</td><td>Decides which providers&#39; image models appear in <strong>Model</strong>. Only OpenAI, Gemini and xAI offer image models.</td></tr><tr><td><strong>API Key</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; Providers</strong></td><td>Connects each provider you use</td></tr></tbody></table><p>With xAI, the size and quality you choose are added to the description rather than sent as separate options, so the results may not match them exactly.</p><p>To set everything up, see <a href="./../configure/magic-ai.html#enable-the-admin-features">Enable the admin features</a>.</p>',9))])}const _=i(d,[["render",h]]);export{I as __pageData,_ as default};
